public static class LevelingTests {
 static int checks;static void Check(bool v,string s){checks++;if(!v)throw new Exception(s);}static void Near(float a,float b,string s,float e=.006f){Check(Math.Abs(a-b)<e,s+" "+a+" vs "+b);}
 static UnityEngine.Transform Child(UnityEngine.Transform p,string n,UnityEngine.Vector3 pos){var t=new UnityEngine.Transform{name=n,parent=p,localPosition=pos};p.children.Add(t);return t;}
 static UnityEngine.MeshFilter Mesh(UnityEngine.Transform t,UnityEngine.Vector3[] v){var f=new UnityEngine.MeshFilter{transform=t,sharedMesh=new UnityEngine.Mesh{vertices=v}};t.components.Add(f);return f;}
 static UnityEngine.BoxCollider Box(UnityEngine.Transform t,UnityEngine.Vector3 size){var b=new UnityEngine.BoxCollider{transform=t,size=size};t.components.Add(b);return b;}
 static ModuleRWGroundDeploy Support(Part p,bool stair=false,string saved=""){
  var r=Child(p.transform,stair?"stairs":"leg",stair?new UnityEngine.Vector3(0,-.89f,1.78f):UnityEngine.Vector3.zero);
  Mesh(r,stair?new[]{new UnityEngine.Vector3(0,0,0),new UnityEngine.Vector3(0,-.05f,.1f),new UnityEngine.Vector3(0,-1.395f,1.79f)}:new[]{new UnityEngine.Vector3(0,-1.2f,0),new UnityEngine.Vector3(0,-1.6f,0),new UnityEngine.Vector3(0,-2.28f,0),new UnityEngine.Vector3(0,-2.19f,0)});
  var foot=Child(r,"foot",stair?new UnityEngine.Vector3(0,-1.365f,1.68f):new UnityEngine.Vector3(0,-2.235f,0));Box(foot,stair?new UnityEngine.Vector3(.17f,.06f,.22f):new UnityEngine.Vector3(.69f,.09f,.69f));
  var trigger=Box(Child(r,"trigger",new UnityEngine.Vector3(0,0,-.1f)),new UnityEngine.Vector3(.5f,1,.2f));trigger.isTrigger=true;
  var n=new ConfigNode();var bind=new ConfigNode{name="TRANSFORM"};bind.values["name"]=r.name;bind.values["deployPosition"]=stair?"0,-.89,1.78":"0,0,0";bind.values["retractPosition"]="0,.7,0";bind.values["retractEuler"]=stair?"-130,0,0":"0,0,0";n.children.Add(bind);
  var d=new ModuleRWGroundDeploy{part=p,deploymentID=stair?"Stairs":"Legs",supportFit=saved};p.modules.Add(d);d.OnLoad(n);d.OnStart(StartState.None);return d;
 }
 static void Fit(ModuleRWGroundDeploy d,int count=1200){for(int i=0;i<count;i++){bool r;Check(d.FitTerrain(UnityEngine.Vector3.up,.02f,out r),"reachable terrain fits");}}
 public static void Run(){
  var p=new Part();var v=new Vessel();p.vessel=v;v.parts.Add(p);UnityEngine.Physics.height=-2.28f;
  var d=Support(p);var r=p.transform.children[0];var f=(UnityEngine.MeshFilter)r.components[0];var original=(UnityEngine.Vector3[])f.sharedMesh.vertices.Clone();
  UnityEngine.Physics.height=-2.58f;Fit(d);Near(float.Parse(d.supportFit,System.Globalization.CultureInfo.InvariantCulture),-.3f,"feet extend to lower terrain");Near(f.mesh.vertices[0].y,-1.2f,"fixed upper sleeve");Near(f.mesh.vertices[2].y,-2.58f,"foot follows terrain");Near(f.mesh.vertices[3].y-f.mesh.vertices[2].y,.09f,"foot thickness unchanged");Near(f.sharedMesh.vertices[2].y,original[2].y,"prefab mesh untouched");
  var box=(UnityEngine.BoxCollider)r.children[0].components[0];Near(box.transform.TransformPoint(box.center).y-box.size.y/2,-2.58f,"physical pad matches visible pad");
  UnityEngine.Physics.height=-2.0f;Fit(d);Near(f.mesh.vertices[2].y,-2,"shortens uphill foot");Check(f.mesh.vertices[1].y>f.mesh.vertices[3].y,"compressed telescope does not invert");
  UnityEngine.Physics.fakePart=new UnityEngine.Collider{owner=p};Fit(d,2);Near(f.mesh.vertices[2].y,-2,"ignores vessel collider ray hits");UnityEngine.Physics.fakePart=null;
  UnityEngine.Physics.height=-3.2f;bool ready;Check(!d.FitTerrain(UnityEngine.Vector3.up,.02f,out ready)&&!ready,"terrain beyond leg stroke rejected");UnityEngine.Physics.missing=true;Check(!d.FitTerrain(UnityEngine.Vector3.up,.02f,out ready),"missing terrain rejected");UnityEngine.Physics.missing=false;UnityEngine.Physics.saturated=true;Check(!d.FitTerrain(UnityEngine.Vector3.up,.02f,out ready),"truncated ray buffer rejected");UnityEngine.Physics.saturated=false;
  var saved=d.supportFit;var p2=new Part{vessel=v};var restored=Support(p2,false,saved);Near(float.Parse(restored.supportFit,System.Globalization.CultureInfo.InvariantCulture),.28f,"saved leg trim restored");Near(((UnityEngine.MeshFilter)p2.transform.children[0].components[0]).mesh.vertices[2].y,-2,"reload reapplies mesh trim before physics");
  d.Retract();for(int i=0;i<150;i++)d.FixedUpdate();Near(f.mesh.vertices[2].y,-2.28f,"raised legs remove trim while folding");Check(!d.FitTerrain(UnityEngine.Vector3.up,.02f,out ready),"raised support not fitted");
  var ps=new Part{vessel=v};var s=Support(ps,true);var sr=ps.transform.children[0];var sm=(UnityEngine.MeshFilter)sr.components[0];var trigger=(UnityEngine.BoxCollider)sr.children[1].components[0];
  UnityEngine.Physics.height=-2.5f;Fit(s);Near(sm.mesh.vertices[0].y,0,"stair landing fixed");Near(sm.mesh.vertices[1].z,.1f,"stair top fixed");Near(trigger.center.y,0,"boarding trigger fixed");var shoe=(UnityEngine.BoxCollider)sr.children[0].components[0];var footY=shoe.transform.TransformPoint(shoe.center).y;Check(footY< -2.4,"stair physical shoe follows visible descent");
  UnityEngine.Physics.height=-2.1f;Fit(s);Check(float.Parse(s.supportFit,System.Globalization.CultureInfo.InvariantCulture)<0,"stairs tilt up to higher ground");UnityEngine.Physics.height=-3.2f;Check(!s.FitTerrain(UnityEngine.Vector3.up,.02f,out ready),"stairs beyond hinge travel rejected");
  // Connected station controls and guard rails, exercising the actual controller.
  v=new Vessel();p=new Part{vessel=v};v.parts.Add(p);var cp=new Part{vessel=v};v.parts.Add(cp);d=Support(p);var sd=Support(p,true);var second=Support(cp);UnityEngine.Physics.height=-2.28f;
  var cmd=new ModuleRWGroundLevel{part=p};p.modules.Add(cmd);var tether=new ModuleRWGroundTether{part=p,tetherEnabled=true};p.modules.Add(tether);cmd.EnableLevel();Check(cmd.leveling&&!tether.tetherEnabled&&cmd.resumeTether,"leveling releases existing tether");
  for(int i=0;i<300;i++){d.FixedUpdate();sd.FixedUpdate();second.FixedUpdate();cmd.FixedUpdate();}
  Check(tether.tetherEnabled&&cmd.levelStatus.Contains("tether"),"tether re-engages after connected supports settle");int before=p.Rigidbody.calls;cmd.FixedUpdate();Check(p.Rigidbody.calls==before,"no force against active tether");
  tether.tetherEnabled=false;cmd.resumeTether=false;p.transform.localRotation=UnityEngine.Quaternion.Euler(0,0,2);cmd.FixedUpdate();Check(p.Rigidbody.calls>before&&p.Rigidbody.lastTorque.magnitude>0,"gentle physical leveling torque");Check(cp.Rigidbody.calls>0,"all connected physical bodies included");Check(p.transform.localRotation.q.Z!=0,"hull orientation not teleported");
  before=p.Rigidbody.calls;TimeWarp.CurrentRateIndex=4;cmd.FixedUpdate();Check(p.Rigidbody.calls==before,"warp applies no leveling force");TimeWarp.CurrentRateIndex=0;v.precalc=new Precalc{isEasingGravity=true};cmd.FixedUpdate();Check(p.Rigidbody.calls==before,"ground physics easing paused");v.precalc=null;v.ctrlState.mainThrottle=1;cmd.FixedUpdate();Check(p.Rigidbody.calls==before,"movement controls pause jacks");v.ctrlState.mainThrottle=0;
  var tube=new ModuleRWCollapsibleTube{part=p,extension=.2f,targetExtension=.6f};p.modules.Add(tube);cmd.FixedUpdate();Check(cmd.levelStatus.Contains("tube")&&p.Rigidbody.calls==before,"tube actuator and leveling never fight");tube.targetExtension=tube.extension;p.transform.localRotation=UnityEngine.Quaternion.Euler(0,0,12);cmd.FixedUpdate();Check(cmd.levelStatus.Contains("limit")&&p.Rigidbody.calls==before,"steep slope rejected");
  cmd.DisableLevel();Check(!cmd.leveling&&cmd.levelStatus.Contains("holding"),"stop holds supports without reset");v.Landed=false;cmd.EnableLevel();Check(!cmd.leveling,"airborne leveling cannot engage");
  Console.WriteLine("PASS "+checks+" leveling assertions: actual mesh/collider fitting, rigid feet/fixed sleeves, landing and boarding trigger, uphill/downhill, restore/fold, ray filtering, travel limits, connected bodies, tether recovery, warp/easing/movement/tube guards; no hull teleport");
 }
}
